function formatDatatable(e,o,a){if(!$(e).length)return;const t="#"+e.replace("#","")+"buscador";$(t).val(""),$(e).DataTable().destroy();const s=$(e).DataTable({paging:!0,ordering:!0,info:!0,searching:!0,searchHighlight:!0,language:{sProcessing:"Procesando...",sLengthMenu:"Ver _MENU_",sZeroRecords:"No se encontraron resultados",sEmptyTable:"Sin Datos",sInfo:"_START_ al _END_ de _TOTAL_ registros",sInfoEmpty:"0",sInfoFiltered:"(total _MAX_ )",sLoadingRecords:"Cargando..."},order:[o,a]});$(".dataTables_filter").css("display","none"),$(".dt-search").css("display","none"),$(t).off("keyup").on("keyup",function(){s.search(this.value).draw()}),$(".dt-length").addClass("d-none");document.querySelector("#table_wrapper .dt-layout-table").nextElementSibling.id="pagingFooter",$("#pagingFooter").removeClass("mt-2").addClass("border mt-0 p-2 rounded-3 rounded-top-0 bg-light").css("margin","12px")}function exportToExcel(e,o){var a=XLSX.utils.book_new(),t=XLSX.utils.json_to_sheet(e);XLSX.utils.book_append_sheet(a,t,"Hoja 1"),XLSX.writeFile(a,o+".xlsx")}